  const pageAdded = (r) => {
    for (const n of r.addedNodes) {
      if (n.nodeType === 1 && n.childElementCount && n.getElementsByTagName("*").length > 40 && !(n.className && /(^|\s)dx/.test(n.className))) return true;
    }
    return false;
  };
  const menuOpened = (r) => {
    for (const n of r.addedNodes) {
      if (n.nodeType === 1 && (/nav-menu/.test(n.className) || n.querySelector('[class*="nav-menu-container"]'))) return true;
    }
    return false;
  };

  const onResize = () => {
    preview.close(true);
    updateAllArrows(true);
  };
  const onOver = (e) => {
    arrowsHover(e);
    preview.onOver(e);
  };
  const onOut = (e) => preview.onOut(e);
  const onHash = () => { document.body.classList.remove("dx-discover-picked"); keyNav.forget(); updateRoute(); scheduleSync(true); };

  // Discover selects its first title by itself (for its side panel): it only shows as selected once
  // you've picked one
  function onDiscoverPick(e) {
    if (e.type === "keydown" && e.key !== "Enter") return;
    const t = e.target;
    if (t instanceof Element && t.closest('#app [class*="discover-content"] [class*="meta-item-container"]')) document.body.classList.add("dx-discover-picked");
  }
  const onTitle = new MutationObserver(brandTitle);

  // ---------------------------------------------------------------------------
  // Built-in extras: subtitle styles, skip intro/credits, picture-in-picture, addon order & backup.
  // Their styles live here (not in the theme) so they also work with other themes.
  // ---------------------------------------------------------------------------

